  fullName: (value) => {
    if (!value.trim()) return "Full name is required.";
    if (value.trim().length < 2) return "Please enter your full name.";
    return "";
  },
  email: (value) => {
    if (!value.trim()) return "Email address is required.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
      return "Please enter a valid email address.";
    return "";
  },
  phone: (value) => {
    if (!value.trim()) return ""; // optional
    if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim()))
      return "Please enter a valid phone number (e.g. +1 555-123-4567).";
    return "";
  },
};

const errorIcon = `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true" focusable="false">
  <circle cx="8" cy="8" r="7.25" stroke="#dc2626" stroke-width="1.5"/>
  <line x1="8" y1="4.5" x2="8" y2="8.5" stroke="#dc2626" stroke-width="1.5" stroke-linecap="round"/>
  <circle cx="8" cy="10.75" r="0.75" fill="#dc2626"/>
</svg>`;

function setError(fieldName, message) {
  const input = document.getElementById(fieldName);
  const errorEl = document.getElementById(`${fieldName}-error`);
  if (!input || !errorEl) return;

  if (message) {
    input.setAttribute("aria-invalid", "true");
    input.setAttribute("aria-describedby",
      [input.getAttribute("aria-describedby") || "", `${fieldName}-error`]
        .join(" ").trim()
    );
    errorEl.innerHTML = `${errorIcon} ${message}`;
  } else {
    input.setAttribute("aria-invalid", "false");
    const described = (input.getAttribute("aria-describedby") || "")
      .replace(`${fieldName}-error`, "").trim();
    if (described) {
      input.setAttribute("aria-describedby", described);
    } else {
      input.removeAttribute("aria-describedby");
    }
    errorEl.innerHTML = "";
  }
}

function validateField(fieldName) {
  const input = document.getElementById(fieldName);
  if (!input) return true;
  const error = validators[fieldName](input.value);
  setError(fieldName, error);
  return !error;
}

function initForm() {
  const form = document.getElementById("contact-form");
  const successBanner = document.getElementById("success-banner");

  // Live validation on blur
  ["fullName", "email", "phone"].forEach((field) => {
    const input = document.getElementById(field);
    if (!input) return;

    input.addEventListener("blur", () => validateField(field));
    input.addEventListener("input", () => {
      // Clear error as user types after a field has been touched
      if (input.getAttribute("aria-invalid") === "true") {
        validateField(field);
      }
    });
  });

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const nameOk = validateField("fullName");
    const emailOk = validateField("email");
    const phoneOk = validateField("phone");

    if (nameOk && emailOk && phoneOk) {
      successBanner.classList.add("visible");
      form.reset();
      ["fullName", "email", "phone"].forEach((f) => {
        const input = document.getElementById(f);
        if (input) {
          input.setAttribute("aria-invalid", "false");
          input.removeAttribute("aria-describedby");
        }
        const errorEl = document.getElementById(`${f}-error`);
        if (errorEl) errorEl.innerHTML = "";
      });
      successBanner.focus();
    } else {
      successBanner.classList.remove("visible");
      // Focus first invalid field
      const firstInvalid = ["fullName", "email", "phone"].find(
        (f) => document.getElementById(f)?.getAttribute("aria-invalid") === "true"
      );
      if (firstInvalid) document.getElementById(firstInvalid).focus();
    }
  });
}

document.addEventListener("DOMContentLoaded", initForm);
